VOWELS = "aeiou"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))


def _translate_word(word):
    if not word:
        return word

    # Rule 1: begins with a vowel, "xr", or "yt" -> just add "ay".
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Otherwise, move the leading consonant cluster to the end.
    # "qu" counts as part of the cluster (Rule 3), and a "y" that
    # follows at least one consonant counts as a vowel (Rule 4).
    i = 0
    while i < len(word):
        c = word[i]
        if c in VOWELS:
            break
        if c == "q" and i + 1 < len(word) and word[i + 1] == "u":
            i += 2
            break
        if c == "y" and i > 0:
            break
        i += 1

    return word[i:] + word[:i] + "ay"
